#![allow(clippy::result_large_err)]

use std::process::ExitCode;

use clap::Parser;

use callisto_cli::cli::{Cli, Command};
use callisto_cli::commands::*;

// Exit code contract for every subcommand
// =========================================
//
// Default rule: every `Err(CliError)` arm below maps to exit code 1 (FAILURE).
// `Ok(code)` is returned verbatim, so each handler owns its own success codes.
//
//   add            0 on success (changeset written or dry-run preview)
//                  1 on any error (NotATty, invalid package spec, I/O, etc.)
//
//   status         0 when --check is not set (always, regardless of diagnostics --
//                    status without --check is informational, never a gate), or
//                    when --check is set and there are no Error-severity diagnostics
//                    (or Warning under --strict), regardless of pending changesets
//                  1 when --check is set and any diagnostic is Error-severity (or
//                    Warning under --strict), regardless of pending changesets
//                  (pending state never affects the exit code: read `pending` from
//                  `--format json`, or the printed count in text output)
//
//   matrix         0 on success (report printed, including an empty report or
//                  one carrying UnrecognisedPlatformTriple warnings)
//                  1 on any error (unknown --package, malformed/wrong-type
//                  manifest, conflicting platform-target sources)
//
//   version        0 on success (versions bumped or dry-run preview)
//                  1 on any error (graph error, strict violation, etc.)
//
//   pre            0 on success
//                  1 on any error
//
//   snapshot       0 on success (snapshot versions applied or dry-run preview)
//                  1 on any error (graph error, Error-severity graph diagnostics
//                  under --strict, etc.)
//
//   init           0 on success (configuration scaffolded or dry-run preview)
//                  1 on any error
//
//   compose-pr-body  0 on success
//                    1 on any error
//
//   release        0 on success, including `Nothing to release.` and --dry-run
//                  1 on any error (dirty worktree, missing credential, CI-only workspace, etc.)
//
//   completions    0 on success
//                  1 on any error
//
//   schema         0 on success
//                  1 on any error

fn main() -> ExitCode {
    let cli = Cli::parse();
    let command_name = cli.command.report_name();

    let res = match cli.command {
        Command::Add(args) => add::handle(args, &cli.global),
        Command::Status(args) => status::handle(args, &cli.global),
        Command::Matrix(args) => matrix::handle(args, &cli.global),
        Command::Version(args) => version::handle(args, &cli.global),
        Command::Pre(args) => pre::handle(args, &cli.global),
        Command::Snapshot(args) => snapshot::handle(args, &cli.global),
        Command::Init(args) => init::handle(args, &cli.global),
        Command::ComposePrBody(args) => compose_pr_body::handle(args, &cli.global),

//! Path-keyed, read-only cache of opened [`Manifest`] handles.
//!
//! A single package manifest (e.g. one `Cargo.toml`) is consulted from
//! several independent read-only sites during a normal command run:
//!
//! 1. [`crate::walk::ManifestWalkResolver::build`] — once (for npm manifests)
//!    to detect [`Manifest::npm_role`], once to collect
//!    [`Manifest::publish_targets`], once more to collect
//!    [`Manifest::iter_dependencies`].
//! 2. [`crate::Workspace::base_versions`] — once to read
//!    [`Manifest::current_version`].
//!
//! Without memoization each of those call sites independently invokes
//! [`callisto_manifests::open`], which re-reads the file from disk and
//! re-parses it, even though nothing on disk can have changed between them
//! within a single read-only command run. [`open_cached`] gives those three
//! sites a shared, path-keyed cache of `Arc<dyn Manifest>` handles so the
//! same manifest is opened at most once per run.
//!
//! This cache is deliberately **read-only**. `Manifest::current_version`,
//! `Manifest::publish_targets`, and `Manifest::iter_dependencies` are all
//! `&self` methods, so sharing a handle behind an `Arc` is sound. The
//! mutation path (`Manifest::write_version` / `Manifest::update_dependency_spec`,
//! invoked from `apply.rs` while applying a version plan) takes `&mut self`
//! and therefore cannot be served from this cache — nor should it be: reusing
//! a cached handle across a write would risk applying an edit against a
//! stale in-memory copy while another cached reader still holds (and might
//! later re-read) the pre-edit state. `apply.rs` intentionally keeps calling
//! `callisto_manifests::open` directly for every write.

use std::cell::RefCell;
use std::collections::BTreeMap;
use std::path::PathBuf;
use std::sync::Arc;

use callisto_manifests::{open, Manifest, OpenContext};
use callisto_model::{ManifestDecl, ManifestError};

/// Opens `decl`, reusing a previously opened handle for the same path from
/// `cache` if one exists. Only suitable for read-only access to the
/// returned handle.
pub(crate) fn open_cached(
    cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
    decl: &ManifestDecl,
    ctx: &OpenContext<'_>,

    /// manifest that was only added later, so it has no blob yet at an
    /// earlier `parent` commit.
    Missing,
}

/// Issues exactly one `git cat-file --batch` invocation requesting every
/// object in `objects` (each `<rev>:<path>`), and returns each result in the
/// same order as `objects`.
///
/// `git cat-file --batch` reads one object identifier per line from stdin
/// and, for each, writes to stdout either:
///
/// ```text
/// <sha> SP <type> SP <size> LF
/// <content: exactly `size` bytes> LF
/// ```
///
/// or, if the object doesn't exist:
///
/// ```text
/// <object> SP missing LF
/// ```
///
/// (git also reports `<object> SP ambiguous LF` for a ref that resolves to
/// more than one object; `<commit>:<path>` syntax should never be
/// ambiguous, but it's checked for explicitly below rather than silently
/// falling through to the blob-header parse.)
///
/// This lets every canonical manifest's content at one commit be fetched in
/// a single subprocess round trip instead of one `git show` per manifest.
///
/// Parsing here is deliberately defensive rather than permissive: this
/// feeds [`derive_release_commit_decision`]'s trust-boundary comparison, so
/// any framing ambiguity -- an unrecognized header shape, a declared `size`
/// that doesn't fit the remaining output, a missing separator byte right
/// after the declared content length, a non-`blob` object type, or a
/// leftover/truncated tail once every requested path has been accounted
/// for -- fails the whole batch closed rather than guessing. Each expected
/// response is also matched against its exact requested object string
/// (rather than a generic "ends with ` missing`" pattern), so a manifest
/// path that happened to contain a space or colon can't be misread as a
/// different response shape. Silently misattributing one manifest's
/// content to a different path because an undetected desync shifted every
/// later offset would be a far worse failure mode than an outright
/// rejection.
pub(crate) fn batch_blobs<R: CommandRunner + ?Sized>(
    runner: &R,
    root: &std::path::Path,
    objects: &[String],
) -> Result<Vec<BatchBlob>, GraphError> {

use std::path::PathBuf;

use clap::{Args, Parser, Subcommand, ValueEnum};

/// Changesets-style version and release manager for Cargo, npm and Python workspaces.
#[derive(Parser)]
#[command(name = "callisto", version, disable_help_subcommand = true)]
pub struct Cli {
    #[command(flatten)]
    pub global: GlobalArgs,
    #[command(subcommand)]
    pub command: Command,
}

/// Flags shared by every subcommand.
#[derive(Args, Clone, Debug)]
pub struct GlobalArgs {
    /// Output format for command results.
    #[arg(long, global = true, value_enum, default_value = "text")]
    pub format: OutputFormat,

    /// Workspace directory to operate in (defaults to the current directory).
    #[arg(long, global = true, default_value = ".")]
    pub cwd: PathBuf,

    #[arg(
        long,
        global = true,
        help = "Preview manifest and file changes without writing to disk"
    )]
    pub dry_run: bool,
}

/// Output rendering mode: human-readable text or machine-readable JSON.
#[derive(ValueEnum, Clone, Copy, Debug, PartialEq, Eq)]
pub enum OutputFormat {
    Text,
    Json,
}

/// A callisto subcommand.
#[derive(Subcommand, Clone, Debug)]
pub enum Command {
    /// Create a new changeset describing pending package changes.
    Add(AddArgs),
    /// Show the workspace's pending changesets and diagnostics.
    Status(StatusArgs),
    /// Print the workspace's native-build target matrix as JSON or a table.
    #[command(hide = true)]
    Matrix(MatrixArgs),
    /// Consume pending changesets and bump package versions accordingly.
    Version(VersionArgs),
    /// Manage prerelease mode for the workspace.
    #[command(subcommand)]
    Pre(PreArgs),
    /// Apply a temporary, non-persistent version bump for a snapshot release.
    Snapshot(SnapshotArgs),
    /// Scaffold Callisto configuration in the current workspace.
    Init(InitArgs),
    /// Generate a pull request body summarizing pending release changes.
    #[command(hide = true)]
    ComposePrBody(ComposePrBodyArgs),
    /// Publish every package whose current version has not been released yet.
    Release(ReleaseCommandArgs),
    /// Decide the next managed release-pull-request operation from a forge snapshot.
    #[command(subcommand, hide = true)]
    ReleasePr(ReleasePrArgs),
    /// Generate shell completion scripts.
    Completions(CompletionsArgs),
    /// Print the JSON schema for a report type.
    #[command(hide = true)]
    Schema(SchemaArgs),
    /// Print a subcommand's help text.
    #[command(hide = true)]
    Help(HelpArgs),
}

impl Command {
    /// The `"command"` value of this invocation's JSON report, success or error: the name below plus, for the
    /// subcommands whose reports carry one (`release plan`, `release-pr verify`), the subcommand.
    pub fn report_name(&self) -> &'static str {
        use callisto_model::{
            ReleaseArtifactManifestReport, ReleaseExecuteReport, ReleasePlanReport, ReleasePrCommitPlanReport,
            ReleasePrDecideReport, ReleasePrVerifyReport, Report,
        };
        match self {
            Command::Release(ReleaseCommandArgs { command: Some(sub), .. }) => match sub {
                ReleaseArgs::Plan(_) => ReleasePlanReport::COMMAND,
                ReleaseArgs::ArtifactManifest(_) => ReleaseArtifactManifestReport::COMMAND,
                ReleaseArgs::Execute(_) => ReleaseExecuteReport::COMMAND,
                ReleaseArgs::Pending(_) | ReleaseArgs::Inspect(_) | ReleaseArgs::BuildPython(_) => "release",
            },
            Command::ReleasePr(ReleasePrArgs::Decide(_)) => ReleasePrDecideReport::COMMAND,
            Command::ReleasePr(ReleasePrArgs::Verify(_)) => ReleasePrVerifyReport::COMMAND,
            Command::ReleasePr(ReleasePrArgs::CommitPlan(_)) => ReleasePrCommitPlanReport::COMMAND,
            other => other.name(),
        }
    }

    /// This subcommand's name exactly as clap parses it, computed from the parsed subcommand rather than duplicated
    /// as a literal at each call site.
    pub fn name(&self) -> &'static str {
        match self {
            Command::Add(_) => "add",
            Command::Status(_) => "status",
            Command::Matrix(_) => "matrix",
            Command::Version(_) => "version",
            Command::Pre(_) => "pre",
            Command::Snapshot(_) => "snapshot",
            Command::Init(_) => "init",
            Command::ComposePrBody(_) => "compose-pr-body",
            Command::Release(_) => "release",
            Command::ReleasePr(_) => "release-pr",
            Command::Completions(_) => "completions",
            Command::Schema(_) => "schema",
            Command::Help(_) => "help",
        }
    }
}

/// Arguments for the `schema` command.
#[derive(Args, Clone, Debug, Default)]
pub struct SchemaArgs {
    /// Report type to print the schema for; defaults to status.
    #[arg(long = "type", value_enum)]
    pub target_type: Option<SchemaReportType>,
}

/// The one registry of report/document types `schema --type` can print --
/// the sole source `SchemaArgs.target_type` and `callisto-cli::commands::schema`
/// both parse and match against, so a new report type is added in one place.
#[derive(ValueEnum, Clone, Copy, Debug, PartialEq, Eq, Default)]
pub enum SchemaReportType {
    #[default]
    Status,
    Version,
    Snapshot,
    Init,
    Changeset,
    /// The on-disk `.changeset/pre.json` file shape -- not `callisto pre`'s
    /// own `--format json` report, which `PreReport` describes instead.
    #[value(name = "pre-state")]
    PreState,
    Matrix,
    ReleaseReceipt,
}

/// Arguments for the hidden `help` subcommand: prints a subcommand's help
/// text even though `disable_help_subcommand` turns off clap's own
/// automatic one, so the visible `--help` listing stays at eight commands.
#[derive(Args, Clone, Debug, Default)]
pub struct HelpArgs {
    /// Subcommand (and nested subcommand) to print help for, e.g. `release plan`; omit for the root help.
    pub command: Vec<String>,
}

/// Arguments for the `add` command.
#[derive(Args, Clone, Debug)]
pub struct AddArgs {
    /// Package and severity to include, as `ecosystem/name:severity` (none, patch, minor, or major); repeatable. Omit to enter the interactive wizard.
    #[arg(long = "package", value_name = "ECOSYSTEM/NAME:SEVERITY")]
    pub packages: Vec<String>,
    /// Human-readable summary of the change to record in the changeset.
    #[arg(long)]
    pub summary: Option<String>,
}

/// Arguments for the `status` command.
#[derive(Args, Clone, Debug)]
pub struct StatusArgs {
    /// Treat warnings as errors (fails with --check)
    #[arg(long)]
    pub strict: bool,
    /// Exit 1 if any diagnostic is an error (pending changesets never fail it)
    #[arg(long)]
    pub check: bool,
}

/// Arguments for the `matrix` command.
#[derive(Args, Clone, Debug, Default)]
pub struct MatrixArgs {
    /// Restrict output to one package, by its ecosystem-qualified id, for example `cargo/foo`.
    #[arg(long)]
    pub package: Option<String>,
}

/// Arguments for the `version` command.
#[derive(Args, Clone, Debug)]
pub struct VersionArgs {
    /// No-op kept for existing callers; lockfile refresh is the default.
    #[arg(long, hide = true)]
    pub refresh_lockfiles: bool,
    /// Skip regenerating lockfiles after applying the version bumps.
    #[arg(long)]
    pub no_refresh_lockfiles: bool,
    /// Treat warning-level diagnostics as errors.
    #[arg(long)]
    pub strict: bool,
    /// Allow versioning to proceed even if no changesets are pending.
    #[arg(long)]
    pub allow_empty_changesets: bool,
    /// Writes the exact release decision this version plan authorizes --
    /// package, target version, and inclusion reason (changeset, fixed
    /// group, linked group, dependency cascade, or pre-release policy) --
    /// to the given path, alongside the manifest and changelog edits.
    ///
    /// A merged release PR's commit carrying this file is later the sole
    /// authority `release plan --from-release-commit` verifies against: no
    /// re-derivation of cascade or group policy happens at that boundary,
    /// only confirmation that the committed diff matches exactly what this
    /// command already decided, once, here.
    #[arg(long, value_name = "PATH")]
    pub emit_decision: Option<std::path::PathBuf>,
}

/// Subcommands for managing prerelease mode.
#[derive(Subcommand, Clone, Debug)]
pub enum PreArgs {
    /// Enter prerelease mode, tagging subsequent version bumps with the given prerelease tag.
    Enter { tag: String },
    /// Exit prerelease mode, returning to normal versioning.
    Exit,
}

/// Arguments for the `snapshot` command.
#[derive(Args, Clone, Debug)]
pub struct SnapshotArgs {
    /// Tag to append to the snapshot version (e.g. a commit SHA or branch name).
    #[arg(long)]
    pub tag: String,
    /// Abort if the workspace graph contains error-severity diagnostics.
    #[arg(long)]
    pub strict: bool,
}

/// Arguments for the `init` command.
#[derive(Args, Clone, Debug, Default)]
pub struct InitArgs {
    /// Run without prompts; required when stdin is not a terminal.
    #[arg(long)]
    pub yes: bool,
    /// Whether packages share one version (fixed) or version independently.
    #[arg(long, value_enum)]
    pub versioning: Option<InitVersioning>,
    /// Ship the product's binaries as GitHub release assets for this Rust target triple (repeatable, comma-separated).
    #[arg(long = "artifact-target", value_name = "TRIPLE", value_delimiter = ',')]
    pub artifact_targets: Vec<String>,
    /// The package whose binaries ship, when several packages produce one.
    #[arg(long, value_name = "PACKAGE")]
    pub product_package: Option<String>,
    /// The GitHub repository (`owner/repo`) binaries are released to.
    #[arg(long, value_name = "OWNER/REPO")]
    pub forge_repository: Option<String>,
    /// Generate `.github/workflows/callisto-release.yml`.
    #[arg(long)]
    pub workflow: bool,
    /// Do not generate a GitHub Actions release workflow.
    #[arg(long)]
    pub no_workflow: bool,
}

/// `init --versioning` values.
#[derive(ValueEnum, Clone, Copy, Debug, PartialEq, Eq)]
pub enum InitVersioning {
    Fixed,
    Independent,
}

/// Arguments for the `compose-pr-body` command.
#[derive(Args, Clone, Debug)]
pub struct ComposePrBodyArgs {
    /// Existing PR body text to merge with, or `-` to read it from stdin.
    #[arg(long, value_name = "TEXT|-")]
    pub existing_body: Option<String>,
    /// Branch name to reference in the generated PR body.
    #[arg(long)]
    pub branch: Option<String>,
}

/// Arguments for the `release` command.
#[derive(Args, Clone, Debug)]
#[command(args_conflicts_with_subcommands = true)]
pub struct ReleaseCommandArgs {
    #[command(subcommand)]
    pub command: Option<ReleaseArgs>,
    /// Release this qualified package, for example `cargo/callisto-cli`, with every distribution of it and the members of its groups. Repeatable.
    #[arg(long = "package", value_name = "ECOSYSTEM/NAME")]
    pub packages: Vec<String>,
    /// Also write the release receipt to this file.
    #[arg(long, value_name = "FILE")]
    pub receipt: Option<PathBuf>,
}

/// Durable release subcommands for the CI plan/build/execute route.
#[derive(Subcommand, Clone, Debug)]
pub enum ReleaseArgs {
    /// List merged release commits whose release never finished, oldest first.
    Pending(ReleasePendingArgs),
    /// Create a read-only durable release intent from exact package selections.
    #[command(hide = true)]
    Plan(ReleasePlanArgs),
    /// Display a durable intent, manifest, or receipt without recomputing it.
    #[command(hide = true)]
    Inspect(ReleaseInspectArgs),
    /// Build the intent's Python distributions without registry credentials, for `artifact-manifest --seal-python`.
    #[command(hide = true)]
    BuildPython(ReleaseBuildPythonArgs),
    /// Create the exact artifact manifest for a completed intent-bound build.
    #[command(hide = true)]
    ArtifactManifest(ReleaseArtifactManifestArgs),
    /// Execute a previously approved intent. This is the only durable mutation route.
    #[command(hide = true)]
    Execute(ReleaseExecuteArgs),
}

/// Read-only managed release-pull-request subcommands.
#[derive(Subcommand, Clone, Debug)]
pub enum ReleasePrArgs {
    /// Derive create, update, or no-op from fresh workspace and forge facts.
    Decide(ReleasePrDecideArgs),
    /// Verify that a freshly collected forge snapshot still matches a prior decision.
    Verify(ReleasePrVerifyArgs),
    /// Build the exact forge commit-API file changes for the staged Git index.
    CommitPlan(ReleasePrCommitPlanArgs),
}

#[derive(Args, Clone, Debug)]
pub struct ReleasePrDecideArgs {
    /// Versioned credential-free forge snapshot JSON, inline JSON, file path, or `-` for stdin.
    #[arg(long, value_name = "FILE|JSON|-")]
    pub snapshot: String,
    /// Exact configured forge repository identity, for example `orin-dx/callisto`.
    #[arg(long, value_name = "OWNER/REPOSITORY")]
    pub repository: String,
    /// Configured base branch for the managed release PR.
    #[arg(long)]
    pub base_branch: String,
    /// Canonical branch managed for the release PR.
    #[arg(long)]
    pub release_branch: String,
}

#[derive(Args, Clone, Debug)]
pub struct ReleasePrVerifyArgs {
    /// Versioned decision JSON, inline JSON, file path, or `-` for stdin.
    #[arg(long, value_name = "FILE|JSON|-")]
    pub decision: String,
    /// Fresh versioned credential-free forge snapshot JSON, inline JSON, file path, or `-` for stdin.
    #[arg(long, value_name = "FILE|JSON|-")]
    pub snapshot: String,
    /// Exact head SHA applied by this executor before checking an update decision.
    #[arg(long)]
    pub applied_head: Option<String>,
}

#[derive(Args, Clone, Debug)]
pub struct ReleasePrCommitPlanArgs {
    /// Full commit SHA the staged changes are relative to (the staging branch's root).
    #[arg(long)]
    pub base_commit: String,
    /// Commit message to record in the plan for the forge commit API.
    #[arg(long)]
    pub message: String,
    /// Write the plan to this file instead of stdout.
    #[arg(long, value_name = "FILE")]
    pub out: Option<PathBuf>,
}

#[derive(Args, Clone, Debug)]
pub struct ReleasePlanArgs {
    /// Read the release source from this checkout while the Callisto binary
    /// itself may come from a separate, current orchestration checkout.
    #[arg(long, value_name = "DIR")]
    pub source_root: Option<PathBuf>,
    /// Exact current coordinator revision whose workflow will attest product assets.
    #[arg(long, value_name = "SHA")]
    pub orchestration_revision: Option<String>,
    /// GitHub repository receiving the product release assets, for example
    /// `orin-dx/callisto`. Required when the workspace declares product assets.
    #[arg(long, value_name = "OWNER/REPOSITORY")]
    pub artifact_repository: Option<String>,
    /// Exact qualified package identity, for example `cargo/callisto-cli`. Repeat this flag to select multiple packages. This local/manual mode cannot be combined with --from-release-commit.
    #[arg(
        long = "package",
        value_name = "ECOSYSTEM/NAME",
        conflicts_with = "from_release_commit",
        required_unless_present = "from_release_commit"
    )]
    pub packages: Vec<String>,
    /// Exact merged release-PR commit checked out in this workspace. CI derives the roster from its versioned manifest delta and never reruns changeset planning.
    #[arg(
        long,
        value_name = "SHA",
        conflicts_with = "packages",
        required_unless_present = "packages",
        requires = "decision"
    )]
    pub from_release_commit: Option<String>,
    /// Exact release-decision JSON path committed alongside the manifest and
    /// changelog edits in the merge commit (written by `callisto version
    /// --emit-decision`). Required with --from-release-commit: this function
    /// verifies the committed diff matches this file exactly rather than
    /// re-deriving changeset, fixed-group, linked-group, cascade, or
    /// pre-release-policy inclusion from scratch.
    #[arg(long, value_name = "FILE")]
    pub decision: Option<PathBuf>,
    /// Explicit path where the immutable intent JSON will be atomically written.
    #[arg(long, value_name = "FILE")]
    pub out: PathBuf,
}

#[derive(Args, Clone, Debug)]
pub struct ReleasePendingArgs {
    /// The committed decision file a release commit writes.
    #[arg(long, value_name = "FILE", default_value = ".callisto/release-decision.json")]
    pub decision: PathBuf,
    /// Count only this release commit and newer ones: the way past a release that cannot finish.
    #[arg(long, value_name = "SHA")]
    pub from: Option<String>,
    /// How many of the newest release commits to examine.
    #[arg(long, value_name = "N", default_value_t = 10)]
    pub limit: usize,
}

#[derive(Args, Clone, Debug)]
pub struct ReleaseInspectArgs {
    /// Explicit path to an intent, artifact manifest, or receipt JSON document.
    #[arg(long, value_name = "FILE")]
    pub input: PathBuf,
}

#[derive(Args, Clone, Debug)]
pub struct ReleaseBuildPythonArgs {
    /// Build from this release-source checkout instead of the current directory.
    #[arg(long, value_name = "DIR")]
    pub source_root: Option<PathBuf>,
    /// Exact durable release intent whose Python publishes are built.
    #[arg(long, value_name = "FILE")]
    pub intent: PathBuf,
    /// Existing directory that receives every sdist and wheel.
    #[arg(long, value_name = "DIR")]
    pub artifact_dir: PathBuf,
}

#[derive(Args, Clone, Debug)]
pub struct ReleaseArtifactManifestArgs {
    /// Exact durable release intent that declares the expected artifact slots.
    #[arg(long, value_name = "FILE")]
    pub intent: PathBuf,
    /// Directory containing one regular file for every declared artifact slot, and with --seal-python the built
    /// distributions.
    #[arg(long, value_name = "DIR")]
    pub artifact_dir: PathBuf,
    /// Also seal the sdist and wheel of every Python publish in the intent, found in the artifact directory.
    #[arg(long)]
    pub seal_python: bool,
    /// Explicit path where the artifact manifest will be atomically written.
    #[arg(long, value_name = "FILE")]
    pub out: PathBuf,
}

#[derive(Args, Clone, Debug)]
pub struct ReleaseExecuteArgs {
    /// Validate and execute against this exact release-source checkout. The
    /// current CLI/orchestration checkout is never inferred from this path.
    #[arg(long, value_name = "DIR")]
    pub source_root: Option<PathBuf>,
    /// Explicit path to the durable release intent JSON document.
    #[arg(long, value_name = "FILE")]
    pub intent: PathBuf,
    /// Explicit artifact manifest path required when the intent declares binary slots.
    #[arg(long, value_name = "FILE")]
    pub artifact_manifest: Option<PathBuf>,
    /// Directory containing the exact regular artifact files named by the manifest.
    /// Required with --artifact-manifest; it is never inferred from the checkout.
    #[arg(long, value_name = "DIR", requires = "artifact_manifest")]
    pub artifact_dir: Option<PathBuf>,
    /// Write the terminal, provider-observed receipt to this explicit path.
    /// A release is not reported successful until this receipt is written.
    #[arg(long, value_name = "FILE")]
    pub receipt: PathBuf,
    /// Exact current coordinator revision that executed this release.
    #[arg(long, value_name = "SHA")]
    pub orchestration_revision: String,
}

/// Arguments for the `completions` command.
#[derive(Args, Clone, Debug)]
pub struct CompletionsArgs {
    /// Shell to generate a completion script for.
    #[arg(value_enum)]
    pub shell: clap_complete::Shell,
}

#[cfg(test)]
mod tests {
    use super::*;
    use clap::CommandFactory;

    /// `Command::name()` is hand-maintained (a `match` per variant), so it can
    /// drift from what clap actually parses each subcommand as; this checks
    /// every one of its outputs against clap's own registered subcommand
    /// names.
    #[test]
    fn command_name_matches_every_clap_subcommand_name() {
        let mut cmd = Cli::command();
        cmd.build();
        let clap_names: std::collections::BTreeSet<&str> = cmd.get_subcommands().map(|s| s.get_name()).collect();

        let variants = [
            Command::Add(AddArgs {
                packages: vec![],
                summary: None,
            }),
            Command::Status(StatusArgs {
                strict: false,
                check: false,
            }),
            Command::Matrix(MatrixArgs::default()),
            Command::Version(VersionArgs {
                refresh_lockfiles: false,
                no_refresh_lockfiles: false,
                strict: false,
                allow_empty_changesets: false,
                emit_decision: None,
            }),
            Command::Pre(PreArgs::Exit),
            Command::Snapshot(SnapshotArgs {
                tag: String::new(),
                strict: false,
            }),
            Command::Init(InitArgs::default()),
            Command::ComposePrBody(ComposePrBodyArgs {
                existing_body: None,
                branch: None,
            }),
            Command::Release(ReleaseCommandArgs {
                command: None,
                packages: vec![],
                receipt: None,
            }),
            Command::ReleasePr(ReleasePrArgs::CommitPlan(ReleasePrCommitPlanArgs {
                base_commit: String::new(),
                message: String::new(),
                out: None,
            })),
            Command::Completions(CompletionsArgs {
                shell: clap_complete::Shell::Bash,
            }),
            Command::Schema(SchemaArgs::default()),
            Command::Help(HelpArgs::default()),
        ];
        for variant in &variants {
            assert!(
                clap_names.contains(variant.name()),
                "Command::name() returned {:?}, which clap does not register as a subcommand name; got: {clap_names:?}",
                variant.name()
            );
        }
    }

    /// `status --strict`/`--check` help text is exact, user-facing wording,
    /// not clap's placeholder or a jargon-laden restatement of the flag name.
    #[test]
    fn status_strict_and_check_help_text_is_exact() {
        let mut cmd = Cli::command();
        cmd.build();

        let status_sub = cmd
            .get_subcommands()
            .find(|s| s.get_name() == "status")
            .expect("status subcommand must exist");

        let help_for = |long: &str| {
            status_sub
                .get_arguments()
                .find(|a| a.get_long() == Some(long))
                .unwrap_or_else(|| panic!("--{long} argument must exist on status subcommand"))
                .get_help()
                .map(|h| h.to_string())
                .unwrap_or_default()
        };

        assert_eq!(help_for("strict"), "Treat warnings as errors (fails with --check)");
        assert_eq!(
            help_for("check"),
            "Exit 1 if any diagnostic is an error (pending changesets never fail it)"
        );
    }

    #[test]
    fn release_plan_requires_exactly_one_authority_mode() {
        use clap::Parser;

        assert!(Cli::try_parse_from(["callisto", "release", "plan", "--out", "intent.json"]).is_err());
        assert!(Cli::try_parse_from([
            "callisto",
            "release",
            "plan",
            "--package",
            "cargo/demo",
            "--from-release-commit",
            "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
            "--out",
            "intent.json",
        ])
        .is_err());
        assert!(Cli::try_parse_from([
            "callisto",
            "release",
            "plan",
            "--from-release-commit",
            "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
            "--out",
            "intent.json",
        ])
        .is_err());
        assert!(Cli::try_parse_from([
            "callisto",
            "release",
            "plan",
            "--from-release-commit",
            "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
            "--decision",
            "release-decision.json",
            "--out",
            "intent.json",
        ])
        .is_ok());
    }

    #[test]
    fn release_artifact_manifest_requires_all_explicit_paths() {
        use clap::Parser;

        assert!(Cli::try_parse_from(["callisto", "release", "artifact-manifest"]).is_err());
        assert!(Cli::try_parse_from([
            "callisto",
            "release",
            "artifact-manifest",
            "--intent",
            "intent.json",
            "--artifact-dir",
            "artifacts",
            "--out",
            "manifest.json",
        ])
        .is_ok());
    }

    /// The legacy publish commands no longer parse.
    #[test]
    fn legacy_publish_commands_are_unrecognized() {
        use clap::Parser;

        for args in [
            vec!["callisto", "publish"],
            vec!["callisto", "plan-publish"],
            vec!["callisto", "tag", "--plan", "plan.json"],
            vec!["callisto", "filter-plan", "--plan", "p.json", "--report", "r.json"],
        ] {
            let error = Cli::try_parse_from(&args)
                .err()
                .unwrap_or_else(|| panic!("{args:?} parsed"));
            assert_eq!(error.kind(), clap::error::ErrorKind::InvalidSubcommand, "{args:?}");
        }
    }

    /// Bare release takes repeatable `--package`, not `--from-release-commit`.
    #[test]
    fn bare_release_accepts_packages_and_rejects_release_commit() {
        use clap::Parser;

        let cli = Cli::try_parse_from([
            "callisto",
            "release",
            "--dry-run",
            "--package",
            "cargo/a",
            "--package",
            "npm/b",
            "--receipt",
            "/tmp/receipt.json",
        ])
        .unwrap();
        assert!(cli.global.dry_run);
        let Command::Release(args) = cli.command else {
            panic!("expected release");
        };
        assert!(args.command.is_none());
        assert_eq!(args.packages, ["cargo/a", "npm/b"]);
        assert_eq!(args.receipt, Some(PathBuf::from("/tmp/receipt.json")));

        let bare = Cli::try_parse_from(["callisto", "release"]).unwrap();
        assert!(matches!(
            bare.command,
            Command::Release(ReleaseCommandArgs { command: None, .. })
        ));

        assert!(Cli::try_parse_from(["callisto", "release", "--from-release-commit", &"a".repeat(40)]).is_err());

